local JQRichTextUtils = require("src/ui/components/reach/richtext/JQRichTextUtils")
local JQRichTextConstants = require("src/ui/components/reach/richtext/JQRichTextConstants")
local JQRichTextFormatModel = class("JQRichTextFormatModel")

function JQRichTextFormatModel:ctor(data)
    data = data or {}
    self:initData(data)
end

function JQRichTextFormatModel:initData(data)
    self.type = data.type or JQRichTextConstants.TYPES.TEXT
    self.text = data.text or ""
    self.fontName = data.fontName or JQRichTextConstants.FONT_NAME
    self.fontSize = data.fontSize or JQRichTextConstants.FONT_SIZE
    self.bold = data.bold or false
    self.underlineWidth = data.underlineWidth or 0
    self.resPath = data.resPath or ""
    self.imgSize = data.imgSize
    self.color = data.color or JQRichTextConstants.COLOR
    self.bgColor = data.bgColor
    self.hasBgColor = not (not self.bgColor)
    self.lineHeight = data.lineHeight or 0
    self.groupIndex = data.groupIndex or 0
    self.groupAlign = data.groupAlign or JQRichTextConstants.ALIGNMENT_LEFT
    self.lineIndex = data.lineIndex or 0
    self.tailWithLF = data.tailWithLF or false
    self:setNullString(data.nullString or false)
    self.clickable = data.clickable or false
    self.isTextSetup = false
end

function JQRichTextFormatModel:setType(type)
    self.type = type
end

function JQRichTextFormatModel:setColor(color)
    self.color = color
end

function JQRichTextFormatModel:setText(text)
    self.isTextSetup = true
    self.text = text
    if text ~= "" then
        self.nullString = false
    end
end

function JQRichTextFormatModel:setBold(bold)
    self.bold = bold
end

function JQRichTextFormatModel:setIsReviseInsert(isReviseInsert)
    self.isReviseInsert = isReviseInsert
end

function JQRichTextFormatModel:setUnderlineWidth(underlineWidth)
    self.underlineWidth = underlineWidth
end

function JQRichTextFormatModel:setFontName(fontName)
    self.fontName = fontName
end

function JQRichTextFormatModel:setFontSize(fontSize)
    self.fontSize = fontSize
end

function JQRichTextFormatModel:setResPath(resPath)
    self.resPath = resPath
end

function JQRichTextFormatModel:setImgSize(imgSize)
    self.imgSize = imgSize
end

function JQRichTextFormatModel:setBgColor(color)
    self.bgColor = color
    self.hasBgColor = not (not self.bgColor)
end

function JQRichTextFormatModel:setHasBgColor(hasBgColor)
    self.hasBgColor = hasBgColor
    if not self.hasBgColor then
        self.bgColor = nil
    end
end

function JQRichTextFormatModel:setLineHeight(lineHeight)
    self.lineHeight = lineHeight
end

function JQRichTextFormatModel:setTailWithLF(tailWithLF)
    self.tailWithLF = tailWithLF
    if tailWithLF then
        self.nullString = false
    end
end

function JQRichTextFormatModel:setNullString(nullString)
    self.nullString = nullString
    if nullString then
        self.text = ""
        self.tailWithLF = false
    end
end

function JQRichTextFormatModel:setEmpty()
    self.text = ""
    self.tailWithLF = false
    self.nullString = false
end

function JQRichTextFormatModel:setGroup(groupIndex, groupAlign)
    self.groupIndex = groupIndex
    self.groupAlign = groupAlign
end

function JQRichTextFormatModel:setGroupIndex(groupIndex)
    self.groupIndex = groupIndex
end

function JQRichTextFormatModel:setGroupAlign(groupAlign)
    self.groupAlign = groupAlign
end

function JQRichTextFormatModel:setLineIndex(lineIndex)
    self.lineIndex = lineIndex
end

function JQRichTextFormatModel:isLF()
    return self.text == "" and self.tailWithLF
end

function JQRichTextFormatModel:getTextLength()
    return self.nullString and 1 or string.utf8len(self.text) + (self.tailWithLF and 1 or 0)
end

function JQRichTextFormatModel:getLength()
    if self.type == JQRichTextConstants.TYPES.TEXT then
        return self.nullString and 1 or string.utf8len(self.text)
    else
        return 1
    end
end

function JQRichTextFormatModel:getOriginalLength()
    if self.type == JQRichTextConstants.TYPES.TEXT then
        return self:getTextLength()
    else
        return 1
    end
end

function JQRichTextFormatModel:getRealLength()
    if self.type == JQRichTextConstants.TYPES.TEXT then
        return string.utf8len(self.text) + (self.tailWithLF and 1 or 0)
    else
        return 1
    end
end

function JQRichTextFormatModel:deleteLastChar()
    if self.tailWithLF then
        self.tailWithLF = false
    elseif self.nullString then
        self.nullString = false
    else
        self:deleteChar(string.utf8len(self.text), 1)
    end
end

function JQRichTextFormatModel:deleteChar(index, length)
    length = length or 1
    local toIndex = index + length - 1
    if toIndex > string.utf8len(self.text) then
        toIndex = string.utf8len(self.text)
    end
    self.text = string.delete(self.text, index, toIndex, true)
end

function JQRichTextFormatModel:insertChar(index, char)
    local text = string.insert(self.text, index, char, true)
    self:setText(text)
end

function JQRichTextFormatModel:split(index, char, newFormat)
    if self.nullString then
        return self:splitOnNullString(char, newFormat)
    elseif index > self:getOriginalLength() then
        return self:splitAtEnd(char, newFormat, false)
    elseif index < 1 then
        return self:splitAtEnd(char, newFormat, true)
    else
        return self:splitIn(index, char, newFormat)
    end
end

function JQRichTextFormatModel:splitOnNullString(char, newFormat)
    local sections = {}
    local format = self:clone():merge(newFormat)
    format:setText(char)
    table.insert(sections, format)
    -- if char == "\n" then
    --    table.insert(sections, format:clone())
    -- end
    return sections
end

function JQRichTextFormatModel:splitAtEnd(char, newFormat, isHead)
    local sections = {}
    local format = self:clone():merge(newFormat)
    format:setText(char)
    format:setTailWithLF(false)
    table.insert(sections, format)
    if isHead then
        table.insert(sections, self:clone())
    else
        table.insert(sections, 1, self:clone())
    end
    return sections
end

function JQRichTextFormatModel:splitIn(index, char, newFormat)
    local beganIndex, endedIndex = index, index - 1
    local divisions = self:divide(beganIndex, endedIndex)

    local sections = {}
    table.foreach(divisions, function(divisionIndex, division)
        local format = self:clone()
        if division[1] == beganIndex and division[2] == endedIndex then
            format:merge(newFormat)
            format:setText(char)
        else
            format:setText(string.utf8sub(self.text, division[1], division[2] - division[1] + 1))
        end
        if divisionIndex ~= #divisions then
            format:setTailWithLF(false)
        else
            format:setTailWithLF(self.tailWithLF)
        end
        table.insert(sections, format)
    end)
    return sections
end

-- newFormat 不是完整的FormatModel
function JQRichTextFormatModel:slice(beganIndex, endedIndex, newFormat)
    if self.nullString then
        return {self:clone():merge(newFormat)}
    end
    local divisions = self:divide(beganIndex, endedIndex)
    local sections = {}
    table.foreach(divisions, function(index, division)
        local format = self:clone()
        format:setText(string.utf8sub(self.text, division[1], division[2] - division[1] + 1))
        if division[1] == beganIndex and division[2] == endedIndex then
            format:merge(newFormat)
        end
        if index ~= #divisions then
            format:setTailWithLF(false)
        end
        table.insert(sections, format)
    end)
    return sections
end

function JQRichTextFormatModel:divide(beganIndex, endedIndex)
    local divisions = {{beganIndex, endedIndex}}
    if beganIndex > 1 then
        table.insert(divisions, 1, {1, beganIndex - 1})
    end
    if endedIndex < self:getLength() then
        table.insert(divisions, {endedIndex + 1, self:getLength()})
    end
    return divisions
end

function JQRichTextFormatModel:copy(format)
    self.type = format.type
    self.text = format.text
    self.fontName = format.fontName
    self.fontSize = format.fontSize
    self.bold = format.bold
    self.underlineWidth = format.underlineWidth
    self.isReviseInsert = format.isReviseInsert
    self.resPath = format.resPath
    self.imgSize = format.imgSize
    self.color = format.color
    self.hasBgColor = format.hasBgColor
    self.bgColor = format.bgColor
    self.lineHeight = format.lineHeight
    self.groupIndex = format.groupIndex
    self.groupAlign = format.groupAlign
    self.lineIndex = format.lineIndex
    self.tailWithLF = format.tailWithLF
    self:setNullString(format.nullString or false)
    self.clickable = format.clickable
    return self
end

function JQRichTextFormatModel:copyProperties()
    return {
        type = self.type,
        text = self.text,
        fontName = self.fontName,
        fontSize = self.fontSize,
        bold = self.bold,
        underlineWidth = self.underlineWidth,
        isReviseInsert = self.isReviseInsert,
        resPath = self.resPath,
        imgSize = self.imgSize,
        color = self.color,
        bgColor = self.bgColor,
        hasBgColor = self.hasBgColor,
        lineHeight = self.lineHeight,
        groupIndex = self.groupIndex,
        groupAlign = self.groupAlign,
        lineIndex = self.lineIndex,
        tailWithLF = self.tailWithLF,
        nullString = self.nullString,
        clickable = self.clickable
    }
end

function JQRichTextFormatModel:merge(format)
    self.type = format.type or self.type
    self.text = format.text or self.text
    self.fontName = format.fontName or self.fontName
    self.fontSize = format.fontSize or self.fontSize
    self.bold = ternary(format.bold == nil, self.bold, format.bold)
    self.underlineWidth = ternary(format.underlineWidth == nil, self.underlineWidth, format.underlineWidth)
    self.isReviseInsert = ternary(format.isReviseInsert == nil, nil, format.isReviseInsert)
    self.resPath = format.resPath or self.resPath
    self.imgSize = format.imgSize or self.imgSize
    self.color = format.color or self.color

    if format.hasBgColor == false then
        self.bgColor = nil
    else
        self.bgColor = format.bgColor or self.bgColor
    end
    self.hasBgColor = not (not self.bgColor)

    self.lineHeight = format.lineHeight or self.lineHeight
    self.groupIndex = format.groupIndex or self.groupIndex
    self.groupAlign = format.groupAlign or self.groupAlign
    self.lineIndex = format.lineIndex or self.lineIndex
    self.tailWithLF = ternary(format.tailWithLF == nil, self.tailWithLF, format.tailWithLF)
    if format.nullString then
        self:setNullString(format.nullString)
    end
    self.clickable = ternary(format.clickable == nil, self.clickable, format.clickable)
    return self
end

function JQRichTextFormatModel:clone()
    return JQRichTextFormatModel.new({
        type = self.type,
        text = self.text,
        fontName = self.fontName,
        fontSize = self.fontSize,
        bold = self.bold,
        underlineWidth = self.underlineWidth,
        resPath = self.resPath,
        imgSize = self.imgSize and {
            width = self.imgSize.width,
            height = self.imgSize.height
        },
        color = {
            r = self.color.r,
            g = self.color.g,
            b = self.color.b
        },
        bgColor = self.bgColor and {
            r = self.bgColor.r,
            g = self.bgColor.g,
            b = self.bgColor.b
        },
        lineHeight = self.lineHeight,
        hasBgColor = self.hasBgColor,
        groupIndex = self.groupIndex,
        groupAlign = self.groupAlign,
        lineIndex = self.lineIndex,
        tailWithLF = self.tailWithLF,
        nullString = self.nullString,
        clickable = self.clickable
    })
end

function JQRichTextFormatModel:getChangedProperties()
    local formats = {}
    if not JQRichTextUtils:isColorEqual(self.color, JQRichTextConstants.COLOR) then
        formats[JQRichTextConstants.HTML.FORMAT_COLOR] = self.color
    end
    if self.fontName ~= JQRichTextConstants.FONT_NAME then
        formats[JQRichTextConstants.HTML.FORMAT_FONT_NAME] = self.fontName
    end
    if self.fontSize ~= JQRichTextConstants.FONT_SIZE then
        formats[JQRichTextConstants.HTML.FORMAT_FONT_SIZE] = self.fontSize
    end
    if self.groupAlign ~= JQRichTextConstants.ALIGNMENT_LEFT then
        formats[JQRichTextConstants.HTML.FORMAT_GROUP_ALIGN] = self.groupAlign
    end
    if self.underlineWidth ~= -1 then
        formats[JQRichTextConstants.HTML.FORMAT_UNDERLINE] = self.underlineWidth
    end
    if self.bold then
        formats[JQRichTextConstants.HTML.FORMAT_BOLD] = self.bold
    end
    if self.hasBgColor then
        formats[JQRichTextConstants.HTML.FORMAT_BG_COLOR] = self.bgColor
    end
    return formats
end

return JQRichTextFormatModel
